import{_ as p,o as e,b as a,q as i}from"./chunks/framework.Tf23FRXt.js";const c=JSON.parse('{"title":"万魔殿 炼净之狱3","description":"","frontmatter":{},"headers":[],"relativePath":"duty/876.htm.md","filePath":"duty/876.md","lastUpdated":1791098838000}'),l={name:"duty/876.htm.md"};function _(r,t,s,n,d,o){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="万魔殿-炼净之狱3" tabindex="-1">万魔殿 炼净之狱 3</h1><p>大树举起小手手时是砸面前，手手攥在一起是砸后场，注意观察大树的手的位置判断 AOE 位置。砸前场的大树手还会向前推，场地上会有箭头提示，躲开箭头即可。</p><p>分散 + 月环，等分散判定结束之后再去站月环，时间来得及，不要提前跑。</p><p>出现距离衰减预兆之后，场地上会有 3 块圆形区域发亮，只有这三块区域是安全的，在三块区域里贴边站即可。</p><p>读条<mark>生命的光芒</mark>是超痛的 AOE，注意放减伤。</p><p>3 块圆台子上掉下来金色的卵，根据卵上的花纹不同有两种情况：</p><ul><li>有圆圈花纹：出现放圆形 AOE 的小怪，3 个台子不安全，前往过道躲避。</li><li>有波浪条花纹：出现放直线俯冲 AOE 的小怪，小怪会有箭头标示俯冲方向，注意观察躲避。</li></ul><p>2 个台子边缘出现地火（带箭头圆形 AOE），根据箭头的方向找到<ins>不会</ins>有地火通过的过道，在那里躲避。</p><p>虚空月环，等 NPC 修复场地后进入安全区域躲避。</p><p>场地修复后会出现 3 组地火，在 2 组地火之间等地火开始前进后，前往地火刚出现的位置回避剩下的地火。</p><p>完整场地的金色卵固定为圆形 AOE 小怪，在中央南北排列一条直线，同时点名玩家分散，注意在场地两侧散开处理。</p><p>场地再次分为三块之后，会出现卵的组合机制：</p><ul><li>圆圈 + 塔：等台子上的 AOE 结束后踩塔</li><li>2 直线 + 1 圆圈 + 击退：可以开防击退处理，亦可被击退至鸟台子后躲避 AOE。</li></ul>',13)])])}const u=p(l,[["render",_]]);export{c as __pageData,u as default};
